import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Scaled dot-product attention specialized for the reference shapes:
//   Q, K, V : (2, 32, 256, 1024) fp16, contiguous
//   out = softmax(Q @ K^T * (1/sqrt(1024))) @ V
// grid = (sequence_length=256, batch*heads=64, 1), block = (256, 1, 1)
// Optimization: stage each query row and 16-key K tiles in shared memory,
// then map 16 consecutive threads to one key so the 1024-dim dot product is
// reduced by in-segment shuffles instead of a block reduction for every key.
.visible .entry attention_kernel(
    .param .u64 pQ,
    .param .u64 pK,
    .param .u64 pV,
    .param .u64 pO
)
{
    .reg .pred %p<12>;
    .reg .b16 %rh<16>;
    .reg .b32 %r<48>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<80>;
    .shared .align 16 .f32 qf[1024];
    .shared .align 16 .b16 ks[16384];
    .shared .align 4 .f32 scores[256];
    .shared .align 4 .f32 red[8];
    .shared .align 4 .f32 bcast[1];
    ld.param.u64 %rd0, [pQ];
    ld.param.u64 %rd1, [pK];
    ld.param.u64 %rd2, [pV];
    ld.param.u64 %rd3, [pO];
    mov.u32 %r0, %tid.x;        // tid   (0..255)
    mov.u32 %r1, %ctaid.x;      // query row index
    mov.u32 %r2, %ctaid.y;      // bh = batch*32 + head
    shl.b32 %r3, %r2, 8;        // bh*256
    add.u32 %r3, %r3, %r1;      // global row
    shl.b32 %r4, %r3, 10;       // qoff = row*1024 (elements)
    shl.b32 %r5, %r2, 18;       // kvbase = bh*262144 (elements)
    and.b32 %r6, %r0, 31;       // lane
    shr.u32 %r7, %r0, 5;        // warp id
    shl.b32 %r24, %r0, 2;       // 4*tid, retained for the value/output pass
    // ---- stage this block's query row into shared memory as f32 ----
    add.u32 %r8, %r4, %r24;
    shl.b32 %r8, %r8, 1;        // bytes
    cvt.u64.u32 %rd4, %r8;
    add.u64 %rd4, %rd4, %rd0;
    ld.global.v2.b32 {%r22, %r23}, [%rd4];
    mov.b32 {%rh0, %rh1}, %r22;
    mov.b32 {%rh2, %rh3}, %r23;
    cvt.f32.f16 %f0, %rh0;
    cvt.f32.f16 %f1, %rh1;
    cvt.f32.f16 %f2, %rh2;
    cvt.f32.f16 %f3, %rh3;
    mov.u32 %r25, qf;
    shl.b32 %r26, %r0, 4;       // tid*16 bytes = 4 f32
    add.u32 %r25, %r25, %r26;
    st.shared.v4.f32 [%r25], {%f0, %f1, %f2, %f3};
    bar.sync 0;
    // ---- pass 1: scores in 16 tiles of 16 keys ----
    mov.u32 %r9, 0;             // key tile id, 0..15
KTILE_LOOP:
    shl.b32 %r26, %r9, 4;       // j0 = tile*16
    shl.b32 %r27, %r26, 10;     // j0*1024
    add.u32 %r27, %r27, %r5;    // tile global element base
    // stage K tile (16 x 1024 fp16 = 32 KiB) with coalesced 16-byte chunks
    mov.u32 %r10, 0;            // chunk iter, 0..7
LDK_LOOP:
    shl.b32 %r11, %r10, 8;      // iter*256
    add.u32 %r11, %r11, %r0;    // chunk id c = iter*256 + tid, 0..2047
    shr.u32 %r12, %r11, 7;      // local key row = c / 128
    and.b32 %r13, %r11, 127;    // 8-half chunk within row
    shl.b32 %r14, %r12, 10;     // row*1024
    shl.b32 %r13, %r13, 3;      // chunk*8 elements
    add.u32 %r14, %r14, %r13;   // local element offset in tile
    add.u32 %r15, %r27, %r14;   // global element offset
    shl.b32 %r15, %r15, 1;      // bytes
    cvt.u64.u32 %rd5, %r15;
    add.u64 %rd5, %rd5, %rd1;
    ld.global.v4.b32 {%r28, %r29, %r30, %r31}, [%rd5];
    shl.b32 %r16, %r14, 1;      // shared byte offset
    mov.u32 %r17, ks;
    add.u32 %r17, %r17, %r16;
    st.shared.v4.b32 [%r17], {%r28, %r29, %r30, %r31};
    add.u32 %r10, %r10, 1;
    setp.lt.u32 %p0, %r10, 8;
    @%p0 bra LDK_LOOP;
    bar.sync 0;
    // 16 consecutive threads cooperate on one key; each owns 64 head dims.
    shr.u32 %r18, %r0, 4;       // key in tile: tid/16, 0..15
    and.b32 %r19, %r0, 15;      // part: tid%16, 0..15
    shl.b32 %r20, %r19, 6;      // part*64
    shl.b32 %r21, %r18, 10;     // key*1024
    add.u32 %r21, %r21, %r20;   // local K element base
    shl.b32 %r28, %r21, 1;      // K shared byte base
    mov.u32 %r22, ks;
    add.u32 %r28, %r28, %r22;
    shl.b32 %r29, %r20, 2;      // Q shared byte base (f32)
    mov.u32 %r22, qf;
    add.u32 %r29, %r29, %r22;
    mov.f32 %f8, 0f00000000;    // partial dot for 64 dims
    mov.u32 %r23, 0;            // 8 chunks of 8 dims
DOT_LOOP:
    ld.shared.v4.b32 {%r30, %r31, %r32, %r33}, [%r28];
    mov.b32 {%rh0, %rh1}, %r30;
    mov.b32 {%rh2, %rh3}, %r31;
    mov.b32 {%rh4, %rh5}, %r32;
    mov.b32 {%rh6, %rh7}, %r33;
    cvt.f32.f16 %f4, %rh0;
    cvt.f32.f16 %f5, %rh1;
    cvt.f32.f16 %f6, %rh2;
    cvt.f32.f16 %f7, %rh3;
    cvt.f32.f16 %f9, %rh4;
    cvt.f32.f16 %f10, %rh5;
    cvt.f32.f16 %f11, %rh6;
    cvt.f32.f16 %f27, %rh7;
    add.u32 %r34, %r29, 16;
    ld.shared.v4.f32 {%f12, %f13, %f14, %f15}, [%r29];
    ld.shared.v4.f32 {%f16, %f17, %f18, %f19}, [%r34];
    mul.f32 %f20, %f12, %f4;
    fma.rn.f32 %f20, %f13, %f5, %f20;
    fma.rn.f32 %f20, %f14, %f6, %f20;
    fma.rn.f32 %f20, %f15, %f7, %f20;
    fma.rn.f32 %f20, %f16, %f9, %f20;
    fma.rn.f32 %f20, %f17, %f10, %f20;
    fma.rn.f32 %f20, %f18, %f11, %f20;
    fma.rn.f32 %f20, %f19, %f27, %f20;
    add.f32 %f8, %f8, %f20;
    add.u32 %r28, %r28, 16;
    add.u32 %r29, %r29, 32;
    add.u32 %r23, %r23, 1;
    setp.lt.u32 %p0, %r23, 8;
    @%p0 bra DOT_LOOP;
    // reduce 16 partials inside each 16-lane segment
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 8, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mov.b32 %r20, %f8;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f9, %r21;
    add.f32 %f8, %f8, %f9;
    mul.f32 %f8, %f8, 0f3D000000;     // scale = 1/sqrt(1024)
    setp.eq.u32 %p1, %r19, 0;
    add.u32 %r13, %r26, %r18;   // global score index j0+key
    mov.u32 %r14, scores;
    shl.b32 %r15, %r13, 2;
    add.u32 %r14, %r14, %r15;
    @%p1 st.shared.f32 [%r14], %f8;
    bar.sync 0;                 // all reads of ks finished before refill
    add.u32 %r9, %r9, 1;
    setp.lt.u32 %p0, %r9, 16;
    @%p0 bra KTILE_LOOP;
    // ---- softmax: block max over scores ----
    mov.u32 %r13, scores;
    shl.b32 %r14, %r0, 2;
    add.u32 %r15, %r13, %r14;
    ld.shared.f32 %f12, [%r15];         // s = scores[tid]
    mov.f32 %f13, %f12;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 16, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 8, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f13, %f13, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r7, 2;
    add.u32 %r11, %r11, %r12;
    @%p0 st.shared.f32 [%r11], %f13;
    bar.sync 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r6, 2;
    add.u32 %r11, %r11, %r12;
    mov.f32 %f15, 0fFF800000;           // -inf
    setp.lt.u32 %p2, %r6, 8;
    setp.eq.u32 %p1, %r7, 0;
    and.pred %p3, %p1, %p2;
    @%p3 ld.shared.f32 %f15, [%r11];
    setp.ne.u32 %p4, %r7, 0;
    @%p4 bra MAX_DONE;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    max.f32 %f15, %f15, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, bcast;
    @%p0 st.shared.f32 [%r11], %f15;
MAX_DONE:
    bar.sync 0;
    mov.u32 %r11, bcast;
    ld.shared.f32 %f16, [%r11];         // row max
    // ---- softmax: e = exp(s - max), block sum of e ----
    sub.f32 %f17, %f12, %f16;
    mul.f32 %f17, %f17, 0f3FB8AA3B;     // * log2(e)
    ex2.approx.f32 %f18, %f17;
    st.shared.f32 [%r15], %f18;         // scores[tid] = e
    mov.f32 %f13, %f18;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 16, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 8, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    mov.b32 %r20, %f13;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f13, %f13, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r7, 2;
    add.u32 %r11, %r11, %r12;
    @%p0 st.shared.f32 [%r11], %f13;
    bar.sync 0;
    mov.u32 %r11, red;
    shl.b32 %r12, %r6, 2;
    add.u32 %r11, %r11, %r12;
    mov.f32 %f15, 0f00000000;
    setp.lt.u32 %p2, %r6, 8;
    setp.eq.u32 %p1, %r7, 0;
    and.pred %p3, %p1, %p2;
    @%p3 ld.shared.f32 %f15, [%r11];
    setp.ne.u32 %p4, %r7, 0;
    @%p4 bra SUM_DONE;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 4, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 2, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f15, %f15, %f14;
    mov.b32 %r20, %f15;
    shfl.sync.down.b32 %r21, %r20, 1, 31, 0xffffffff;
    mov.b32 %f14, %r21;
    add.f32 %f15, %f15, %f14;
    setp.eq.u32 %p0, %r6, 0;
    mov.u32 %r11, bcast;
    @%p0 st.shared.f32 [%r11], %f15;
SUM_DONE:
    bar.sync 0;
    mov.u32 %r11, bcast;
    ld.shared.f32 %f19, [%r11];         // softmax denominator
    mov.f32 %f20, 0f3F800000;           // 1.0f
    div.rn.f32 %f21, %f20, %f19;        // 1 / sum
    // ---- pass 2: out = (sum_j e_j * v_j) / sum ----
    mov.f32 %f22, 0f00000000;
    mov.f32 %f23, 0f00000000;
    mov.f32 %f24, 0f00000000;
    mov.f32 %f25, 0f00000000;
    mov.u32 %r9, 0;
OUT_LOOP:
    mov.u32 %r13, scores;
    shl.b32 %r14, %r9, 2;
    add.u32 %r13, %r13, %r14;
    ld.shared.f32 %f26, [%r13];         // e_j (broadcast)
    shl.b32 %r10, %r9, 10;
    add.u32 %r10, %r10, %r5;
    add.u32 %r10, %r10, %r24;
    shl.b32 %r10, %r10, 1;
    cvt.u64.u32 %rd5, %r10;
    add.u64 %rd5, %rd5, %rd2;
    ld.global.v2.b32 {%r22, %r23}, [%rd5];
    mov.b32 {%rh0, %rh1}, %r22;
    mov.b32 {%rh2, %rh3}, %r23;
    cvt.f32.f16 %f4, %rh0;
    cvt.f32.f16 %f5, %rh1;
    cvt.f32.f16 %f6, %rh2;
    cvt.f32.f16 %f7, %rh3;
    fma.rn.f32 %f22, %f26, %f4, %f22;
    fma.rn.f32 %f23, %f26, %f5, %f23;
    fma.rn.f32 %f24, %f26, %f6, %f24;
    fma.rn.f32 %f25, %f26, %f7, %f25;
    add.u32 %r9, %r9, 1;
    setp.lt.u32 %p0, %r9, 256;
    @%p0 bra OUT_LOOP;
    mul.f32 %f22, %f22, %f21;
    mul.f32 %f23, %f23, %f21;
    mul.f32 %f24, %f24, %f21;
    mul.f32 %f25, %f25, %f21;
    // ---- store output row (fp32 -> fp16) ----
    cvt.rn.f16.f32 %rh0, %f22;
    cvt.rn.f16.f32 %rh1, %f23;
    cvt.rn.f16.f32 %rh2, %f24;
    cvt.rn.f16.f32 %rh3, %f25;
    mov.b32 %r22, {%rh0, %rh1};
    mov.b32 %r23, {%rh2, %rh3};
    add.u32 %r8, %r4, %r24;
    shl.b32 %r8, %r8, 1;
    cvt.u64.u32 %rd4, %r8;
    add.u64 %rd4, %rd4, %rd3;
    st.global.v2.b32 [%rd4], {%r22, %r23};
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("attention_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        out = torch.empty(Q.shape, dtype=Q.dtype, device=Q.device)
        batch_size, num_heads, sequence_length, embedding_dimension = Q.shape
        module = _get_ptx_module()
        module.launch(
            "attention_kernel",
            grid=(sequence_length, batch_size * num_heads, 1),
            block=(256, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

